CREATE DATABASE IF NOT EXISTS bryleigh CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE bryleigh;
CREATE TABLE IF NOT EXISTS users (user_id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('customer','admin') NOT NULL DEFAULT 'customer', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS categories (category_id INT AUTO_INCREMENT PRIMARY KEY, category_name VARCHAR(50) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (product_id INT AUTO_INCREMENT PRIMARY KEY, category_id INT NOT NULL, title VARCHAR(150) NOT NULL, description TEXT, price DECIMAL(10,2) NOT NULL, item_condition ENUM('Like New','Good','Fair') NOT NULL, stock INT NOT NULL DEFAULT 0, image_path VARCHAR(255) NULL, status ENUM('active','archived') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories(category_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (order_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, total_amount DECIMAL(10,2) NOT NULL, payment_method VARCHAR(50) NOT NULL, payment_reference VARCHAR(100) NULL, delivery_option ENUM('Standard','Express','Pick-up') NOT NULL, payment_status ENUM('pending','paid') NOT NULL DEFAULT 'pending', shipping_status ENUM('not_shipped','shipped','delivered') NOT NULL DEFAULT 'not_shipped', order_status ENUM('pending','completed','cancelled') NOT NULL DEFAULT 'pending', ship_name VARCHAR(150) NOT NULL, ship_phone VARCHAR(50) NOT NULL, ship_address VARCHAR(255) NOT NULL, ship_city VARCHAR(100) NOT NULL, ship_province VARCHAR(100) NOT NULL, ship_zip VARCHAR(20) NOT NULL, ship_region VARCHAR(100) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_orders_user FOREIGN KEY (user_id) REFERENCES users(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_items (order_item_id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, product_id INT NOT NULL, quantity INT NOT NULL, price_at_sale DECIMAL(10,2) NOT NULL, CONSTRAINT fk_items_order FOREIGN KEY (order_id) REFERENCES orders(order_id) ON DELETE CASCADE, CONSTRAINT fk_items_product FOREIGN KEY (product_id) REFERENCES products(product_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

